# LÓGICA DO SERVIDOR (SERVER)
# ===================================================================================
server <- function(input, output, session) {
  
  log_text <- reactiveVal("Aguardando o upload do arquivo PDF...")
  processed_data_rv <- reactiveVal(NULL)
  excel_download_data <- reactiveVal(NULL)
  debug_log_rv <- reactiveVal("Aguardando processamento para depuração...")
  
  output$data_is_ready <- reactive({
    !is.null(processed_data_rv())
  })
  outputOptions(output, "data_is_ready", suspendWhenHidden = FALSE)
  
  output$debug_text <- renderText({ debug_log_rv() })
  
  observeEvent(input$pdf_file, {
    req(input$pdf_file)
    shinyjs::show("process_button_container")
    shinyjs::hide("reset_button_ui")
    log_text(paste0("Arquivo '", input$pdf_file$name, "' carregado.\nIniciando leitura do conteúdo no navegador... Aguarde."))
    processed_data_rv(NULL)
    excel_download_data(NULL)
    debug_log_rv("Aguardando processamento para depuração...")
  })
  
  observeEvent(input$pdf_text_pages, {
    req(input$pdf_file$name)
    
    full_text <- paste(input$pdf_text_pages, collapse = "\n")
    
    if (stringr::str_detect(full_text, "Relatório de pesquisa de preço")) {
      log_text(paste0("Arquivo '", input$pdf_file$name, "' lido. Formato válido.\nPronto! Clique em processar para gerar a planilha Excel."))
      
      showNotification(
        "✅ Formato de PDF reconhecido.",
        duration = 5,
        type = "message",
        closeButton = FALSE
      )
      
      shinyjs::enable("process_button")
    } else {
      log_text(paste0("Arquivo '", input$pdf_file$name, "' lido. Formato INVÁLIDO.\nPor favor, selecione um 'Relatório de pesquisa de preço' do Compras.gov.br."))
      
      showNotification(
        "⚠️ Formato de PDF não reconhecido. Verifique o arquivo.",
        type = "warning",
        duration = 10
      )
      
      shinyjs::disable("process_button")
    }
  })
  
  observeEvent(input$pdf_text_pages_error, ignoreInit = TRUE, {
    log_text(paste(log_text(), "\n[AVISO] Falha do leitor PDF no navegador:", input$pdf_text_pages_error))
  })
  
  output$status_text <- renderText({ log_text() })
  
  output$process_button_ui <- renderUI({
    req(input$pdf_file)
    
    if (is.null(input$pdf_text_pages)) {
      actionButton("loading_button", "Lendo o PDF no navegador...", icon = icon("spinner", class = "fa-spin"), class = "btn-secondary btn-lg w-100", disabled = TRUE)
    } else {
      actionButton("process_button", "Processar e Baixar Planilha Excel", icon = icon("cogs"), class = "btn-primary btn-lg w-100")
    }
  })
  
  output$reset_button_ui <- renderUI({
    actionButton("reset_button", "Limpar e Recomeçar", icon = icon("eraser"), class = "btn-outline-danger w-100 mt-2")
  })
  
  shinyjs::hide("reset_button_ui")
  
  observeEvent(input$reset_button, {
    shinyjs::reset("pdf_file")
    shinyjs::hide("process_button_container")
    shinyjs::hide("reset_button_ui")
    
    shinyjs::runjs("document.getElementById('pdf_file').value = ''; Shiny.setInputValue('pdf_text_pages', null, {priority: 'event'});")
    
    processed_data_rv(NULL)
    excel_download_data(NULL)
    log_text("Aguardando o upload do arquivo PDF...")
    debug_log_rv("Aguardando processamento para depuração...")
    updateTabsetPanel(session, "main_tabs", selected = "Início e Status")
