        session$sendCustomMessage(type = "download_b64", message = list(data = encoded_data, filename = filename, mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
        
        excel_download_data(list(data = encoded_data, filename = filename, mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
        
        setProgress(1, detail = "Concluído!")
        log_text(paste(log_text(), "\nSucesso! O download foi iniciado."))
        process_success <- TRUE
        
        updateTabsetPanel(session, "main_tabs", selected = "Resumo da Extração")
        
      }, error = function(e) {
        log_text(paste(log_text(), "\n\n--- ERRO DURANTE O PROCESSAMENTO ---\n", e$message, "\n", paste(capture.output(traceback()), collapse = "\n")))
        processed_data_rv(NULL)
        excel_download_data(NULL)
        
        error_title <- "Ocorreu um Erro Inesperado"
        error_message <- "Ocorreu um erro durante o processamento. Verifique o log de status para detalhes técnicos. Se o problema persistir, contate o suporte."
        
        if (grepl("Nenhum dado de cotação válido foi extraído", e$message, ignore.case = TRUE)) {
          error_title <- "Formato de PDF Inválido"
          error_message <- "Não foi possível extrair os dados. A aplicação funciona exclusivamente com o PDF de 'Relatório de pesquisa de preço' gerado pelo sistema Compras.gov.br. Por favor, verifique se o arquivo carregado está no formato correto."
        }
        
        showModal(modalDialog(
          title = tagList(icon("times-circle", class="text-danger"), " ", error_title),
          error_message,
          footer = modalButton("Fechar"),
          easyClose = TRUE
        ))
      }, finally = {
        if (process_success) {
          shinyjs::show("reset_button_ui")
        } else {
          shinyjs::show("process_button_container")
        }
        
        if (!is.null(tmp_xlsx_path) && file.exists(tmp_xlsx_path)) unlink(tmp_xlsx_path)
      })
    })
  })
  
