  output$summary_details_output <- renderText({
    data <- processed_data_rv()
    req(data, cancelOutput = TRUE)
    
    original_quotes_df <- data$quotes
    req(nrow(original_quotes_df) > 0)
    
    selected_research_val <- input$summary_selected_research
    
    quotes_to_process <- if (!is.null(selected_research_val) && selected_research_val != "all" && selected_research_val != "") {
      original_quotes_df %>% filter(`Número da Pesquisa` == selected_research_val)
    } else {
      original_quotes_df
    }
    
    pesquisas_str <- if (!is.null(selected_research_val) && selected_research_val != "all" && selected_research_val != "") {
      selected_research_val
    } else {
      paste(unique(original_quotes_df$`Número da Pesquisa`), collapse = ", ")
    }
    
    incisos_por_item <- quotes_to_process %>%
      filter(Compõe == "Sim" & !is.na(`Preço unitário`) & !is.na(Inciso)) %>%
      group_by(`Número da Pesquisa`, Item) %>%
      summarise(INCISOS_CONCAT = paste(sort(unique(Inciso)), collapse = ","), .groups = 'drop')
    
    count_I           <- sum(incisos_por_item$INCISOS_CONCAT == "I")
    count_II          <- sum(incisos_por_item$INCISOS_CONCAT == "II")
    count_III         <- sum(incisos_por_item$INCISOS_CONCAT == "III")
    count_IV          <- sum(incisos_por_item$INCISOS_CONCAT == "IV")
    count_V           <- sum(incisos_por_item$INCISOS_CONCAT == "V")
    count_combinados  <- sum(stringr::str_detect(incisos_por_item$INCISOS_CONCAT, ","))
    
    items_less_than_3_quotes <- quotes_to_process %>%
      filter(Compõe == "Sim" & !is.na(`Preço unitário`)) %>%
      group_by(`Número da Pesquisa`, Item) %>%
      summarise(n_quotes = n(), .groups = 'drop') %>%
      filter(n_quotes < 3) %>%
      nrow()
    
    unproven_quotes_count <- quotes_to_process %>%
      filter(
        Inciso %in% c("III", "IV", "V"),
        (is.na(`Endereço Eletrônico`) | str_trim(`Endereço Eletrônico`) == "") &
          (is.na(Anexo) | str_trim(Anexo) == "")
      ) %>%
      nrow()
    
    total_itens_pool_III_IV_V <- incisos_por_item %>%
      filter(str_detect(INCISOS_CONCAT, "III|IV|V")) %>%
      nrow()
    
    details_text <- paste(
      paste("Arquivo Processado:", input$pdf_file$name),
      "------------------------------------",
      paste("Números das Pesquisas:", pesquisas_str),
      "------------------------------------",
      "Parâmetros utilizados nas pesquisas de preços (contagem de itens):",
      sprintf("I   – Compras.gov.br: %d", count_I),
      sprintf("II  – Contratações similares: %d", count_II),
      sprintf("III – Sites Especializados: %d", count_III),
      sprintf("IV  – Fornecedor: %d", count_IV),
      sprintf("V   – Notas Fiscais: %d", count_V),
      sprintf("Parâmetros Combinados: %d", count_combinados),
      "------------------------------------",
      "Observação:",
      sprintf("- Foram encontrados %d itens com menos de 3 cotações válidas.", items_less_than_3_quotes),
      sprintf("- Dentre os %d itens que utilizaram os parâmetros III, IV ou V, foram encontradas %d cotações sem a devida comprovação (endereço eletrônico e/ou anexo).", total_itens_pool_III_IV_V, unproven_quotes_count),
      sep = "\n"
    )
    
    integrity_text <- ""
    
    if (!is.null(selected_research_val) && nzchar(selected_research_val)) {
      check_result <- ""
      if (selected_research_val == "all") {
        all_researches <- unique(original_quotes_df$`Número da Pesquisa`)
        failed_researches <- c()
        
        for(current_research in all_researches) {
          pesquisa_quotes <- original_quotes_df %>%
            filter(`Número da Pesquisa` == current_research) %>%
            mutate(Item = as.integer(Item), `Nº Cotação` = as.integer(`Nº Cotação`))
          
          unique_items <- sort(unique(pesquisa_quotes$Item))
          
          research_has_failure <- FALSE
          for (current_item in unique_items) {
            item_quote_numbers <- pesquisa_quotes %>%
              filter(Item == current_item) %>%
              pull(`Nº Cotação`) %>%
              unique() %>%
              sort()
            
            if (length(item_quote_numbers) >= 2) {
              min_q <- min(item_quote_numbers, na.rm = TRUE)
              max_q <- max(item_quote_numbers, na.rm = TRUE)
              
              expected_seq <- seq(from = min_q, to = max_q)
              missing_quotes <- setdiff(expected_seq, item_quote_numbers)
              
              if (length(missing_quotes) > 0) {
                failed_researches <- c(failed_researches, current_research)
                research_has_failure <- TRUE
                break
              }
            }
          }
          if (research_has_failure) next
        }
        
        if (length(failed_researches) == 0) {
          total_items <- data$item_count
          check_result <- paste0("✅ Sucesso! Todas as cotações listadas para os ", total_items, " itens dessa pesquisa foram coletadas.")
        } else {
          failed_list <- paste(unique(failed_researches), collapse = ", ")
          check_result <- paste0("⚠️ Atenção! As seguintes pesquisas apresentaram falhas na sequência de cotações: ", failed_list, ". Para ver os detalhes, selecione cada pesquisa individualmente no menu acima.")
        }
        
      } else {
        pesquisa_quotes <- original_quotes_df %>%
          filter(`Número da Pesquisa` == selected_research_val) %>%
          mutate(Item = as.integer(Item), `Nº Cotação` = as.integer(`Nº Cotação`))
        
        if (nrow(pesquisa_quotes) == 0) {
          check_result <- paste("Nenhuma cotação encontrada para a pesquisa", selected_research_val)
        } else {
          unique_items <- sort(unique(pesquisa_quotes$Item))
          failed_items <- c()
          
          for (current_item in unique_items) {
            item_quote_numbers <- pesquisa_quotes %>%
              filter(Item == current_item) %>%
              pull(`Nº Cotação`) %>%
              unique() %>%
              sort()
            
            if (length(item_quote_numbers) >= 2) {
              min_q <- min(item_quote_numbers, na.rm = TRUE)
              max_q <- max(item_quote_numbers, na.rm = TRUE)
              
              expected_seq <- seq(from = min_q, to = max_q)
              missing_quotes <- setdiff(expected_seq, item_quote_numbers)
              
              if (length(missing_quotes) > 0) {
                failed_items <- c(failed_items, current_item)
              }
            }
          }
          
          if (length(failed_items) == 0) {
            total_items <- length(unique_items)
            check_result <- paste0("✅ Sucesso! Todas as cotações listadas para os ", total_items, " itens dessa pesquisa foram coletadas.")
          } else {
            if (length(failed_items) > 1) {
              failed_items_str <- paste(paste(head(failed_items, -1), collapse = ", "), "e", tail(failed_items, 1))
            } else {
              failed_items_str <- as.character(failed_items)
            }
            check_result <- paste0("⚠️ Atenção! Os itens ", failed_items_str, " não tiveram todas as suas cotações coletadas.")
          }
        }
      }
      
      integrity_text <- paste(
        "------------------------------------",
        "Verificação de Integridade:",
        check_result,
        sep="\n"
      )
    }
    
    paste(details_text, integrity_text, sep = "\n")
  })
  
