  plot_generator <- function() {
    plot_data <- filtered_plot_data()
    req(plot_data, nrow(plot_data) > 0)
    
    stats_data <- plot_data
    mean_price <- if(nrow(stats_data) > 0) mean(stats_data$`Preço unitário`, na.rm = TRUE) else NA
    median_price <- if(nrow(stats_data) > 0) median(stats_data$`Preço unitário`, na.rm = TRUE) else NA
    
    plot_data <- plot_data %>% arrange(desc(`Preço unitário`))
    
    op <- par(scipen = 999)
    on.exit(par(op))
    
    item_info <- plot_data %>%
      summarise(CATMAT = first(CATMAT), Descricao = first(`Descrição do Item`)) %>%
      head(1)
    
    main_title <- paste("Preços Unitários para o Item:", input$selected_item)
    
    desc_text_raw <- item_info$Descricao
    desc_wrapped <- strwrap(paste(" ", desc_text_raw), width = 110)
    desc_first_line <- desc_wrapped[1]
    desc_other_lines <- if(length(desc_wrapped) > 1) desc_wrapped[-1] else character(0)
    
    num_desc_lines <- length(desc_wrapped)
    
    top_margin_lines <- 12 + num_desc_lines + 1
    
    plot_data$Nome_curto <- sapply(plot_data$Nome_curto, function(name) {
      paste(strwrap(name, width = 60), collapse = "\n")
    })
    
    longest_line_after_wrap <- max(sapply(strsplit(plot_data$Nome_curto, "\n"), function(lines) max(nchar(lines))))
    left_margin_inches <- 0.07 * longest_line_after_wrap + 1.2
    
    left_margin_lines <- left_margin_inches / par("cin")[2]
    
    par(mar = c(5.1, left_margin_lines, top_margin_lines, 4.1), family = "sans", bg = "white")
    
    colors <- ifelse(plot_data$Compõe == "Sim", "#1E8449", "#6C757D")
    
    bp <- barplot(plot_data$`Preço unitário`, horiz = TRUE,
                  names.arg = plot_data$Nome_curto, las = 1,
                  col = colors, border = NA,
                  xlab = "Preço Unitário (R$)",
                  cex.names = 0.8,
                  xlim = c(0, max(plot_data$`Preço unitário`, na.rm = TRUE) * 1.35),
                  axes = FALSE,
                  space = 1.2)
    
    axis_ticks <- pretty(c(0, plot_data$`Preço unitário`))
    axis(1, at = axis_ticks, labels = format_currency_br(axis_ticks))
    
    box(bty = "l")
    
    if(!is.na(mean_price))  abline(v = mean_price,   col = "#E67E22", lty = 2, lwd = 2)
    if(!is.na(median_price)) abline(v = median_price, col = "#428BCA", lty = 2, lwd = 2)
    
    labels <- format_currency_br(plot_data$`Preço unitário`)
    prices <- plot_data$`Preço unitário`
    
    text(x = prices,
         y = bp,
         label = labels,
         col = "black",
         pos = 4,
         cex = 1.0)
    
    mtext(main_title, side = 3, line = top_margin_lines - 2.5, adj = 0.35, cex = 1.4, font = 2)
    
    line_pesquisa <- top_margin_lines - 4.0
    line_catmat <- line_pesquisa - 1.2
    line_desc_title <- line_catmat - 1.2
    
    mtext(bquote(bold("Pesquisa Nº:") ~ .(input$selected_research)), side = 3, line = line_pesquisa, adj = 0.0, cex = 1)
    mtext(bquote(bold("CATMAT:") ~ .(item_info$CATMAT)), side = 3, line = line_catmat, adj = 0.0, cex = 0.9)
    mtext(bquote(bold("Descrição:") ~ .(desc_first_line)), side = 3, line = line_desc_title, adj = 0.0, cex = 0.9, font=3)
    
    if(length(desc_other_lines) > 0) {
      for (i in seq_along(desc_other_lines)) {
        mtext(desc_other_lines[[i]], side = 3, line = line_desc_title - (i * 1.1), adj = 0.0, cex = 0.9, font = 3)
      }
    }
    
    mean_val_str   <- format_currency_br(mean_price)
    median_val_str <- format_currency_br(median_price)
    
    legend_labels <- c(
      "■ Cotação Válida",
      "■ Cotação Descartada",
      paste("- - - Média:", mean_val_str),
      paste("- - - Mediana:", median_val_str)
    )
    
    legend_colors <- c("#1E8449", "#6C757D", "#E67E22", "#428BCA")
    
    legend_line <- line_desc_title - (num_desc_lines * 1.1) - 1.5
    
    adj_positions <- c(0.0, 0.25, 0.55, 0.9)
    
    for (i in seq_along(legend_labels)) {
      mtext(legend_labels[[i]], side = 3, line = legend_line, adj = adj_positions[[i]], cex = 1.1, col = legend_colors[[i]], font = 2)
    }
  }
  
